  (* [comment removed for export] *)
  Lemma rec_vs_regc : forall x, In x (chunk_list st) ->
    (ch_end x <= RB s c + au \/ RB s c + 4294967296 <= ch_lo x \/ ch_end x <= RB s c) /\ (a_ri s + kPageSize <= ch_lo x \/ ch_end x <= a_ri s)
