    Lemma ZR_sh : forall lo' kk a, 0 <= lo' -> lo' mod 8 = 0 -> 0 <= kk -> lo' + 8 * kk <= aceil ->
      (lo' + 8 * kk <= RB s c + mu \/ RB s c + mu' <= lo') -> (lo' + 8 * kk <= FA s c + mfa \/ FA s c + mfa' <= lo') ->
